// <auto-generated />
import { useCallback, useEffect, useRef, useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useApiService } from './useApiService';
import { ApiError } from '../errors/ApiError';
import type { CreateSubscriptionRequest, NotificationEvent, NotificationEvents, Subscription, Subscriptions } from '../models';
import type { NotificationType } from '../enums';

const notificationsKeys = {
  all: ['notifications'] as const,
  listSubscriptions: () => [...notificationsKeys.all, 'listSubscriptions'] as const,
  detail: (subscriptionId: string) => [...notificationsKeys.all, 'detail', subscriptionId] as const,
};

export { notificationsKeys };

export function useListSubscriptions() {
  const api = useApiService();
  return useQuery({
    queryKey: notificationsKeys.listSubscriptions(),
    queryFn: async () => {
      const result = await api.notifications.listSubscriptions();
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
  });
}

export function useCreateSubscription() {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (body: CreateSubscriptionRequest) => {
      const result = await api.notifications.createSubscription(body);
      if (result.status === 'created') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: notificationsKeys.all });
    },
  });
}

export function useGetSubscriptionById(subscriptionId: string) {
  const api = useApiService();
  return useQuery({
    queryKey: notificationsKeys.detail(subscriptionId),
    queryFn: async () => {
      const result = await api.notifications.getSubscriptionById(subscriptionId);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    enabled: !!subscriptionId,
  });
}

export function useDeleteSubscription() {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (subscriptionId: string) => {
      const result = await api.notifications.deleteSubscription(subscriptionId);
      if (result.status === 'noContent') {
        return;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: notificationsKeys.all });
    },
  });
}

export function useListNotificationsStream(query?: { topics?: string /* default: 'system,user,data' */ }, options?: { enabled?: boolean }) {
  const api = useApiService();
  const [items, setItems] = useState<readonly NotificationEvent[]>([]);
  const [status, setStatus] = useState<'idle' | 'streaming' | 'success' | 'error'>('idle');
  const [error, setError] = useState<Error | null>(null);
  const controllerRef = useRef<AbortController | null>(null);

  const cancel = useCallback(() => {
    controllerRef.current?.abort();
    controllerRef.current = null;
    setStatus('idle');
  }, []);

  const reset = useCallback(() => {
    cancel();
    setItems([]);
    setError(null);
  }, [cancel]);

  const enabled = options?.enabled !== false;
  const keyDep = JSON.stringify({ query });

  useEffect(() => {
    if (!enabled) return;

    const controller = new AbortController();
    controllerRef.current = controller;
    setStatus('streaming');
    setItems([]);
    setError(null);

    let buffer: NotificationEvent[] = [];
    (async () => {
      try {
        for await (const item of api.notifications.listNotifications(query, controller.signal)) {
          if (controller.signal.aborted) return;
          buffer = [...buffer, item];
          setItems(buffer);
        }
        if (!controller.signal.aborted) setStatus('success');
      } catch (err) {
        if (controller.signal.aborted) return;
        if (err instanceof DOMException && err.name === 'AbortError') return;
        setError(err as Error);
        setStatus('error');
      }
    })();

    return () => controller.abort();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, keyDep]);

  return { items, status, error, cancel, reset };
}